-- Preflight: abort rather than touch a database with operational attempts or manual scores.
lock table public.exam_attempts in share row exclusive mode;
do $$begin
 if exists(select 1 from public.exam_attempts where organization_id='6e143c55-7be5-4e6e-9f1a-8f8db429956a') or exists(select 1 from public.grade_items where source='manual') or (select count(*) from public.exam_attempts)>2 then
 raise exception 'Preflight changed: operational attempts/manual grades detected; review and back up again';
 end if;
end$$;
alter table public.exam_attempts add column class_snapshot uuid[] not null default '{}',add column grading_revision integer not null default 0,add column passed boolean;
create function private.capture_attempt_classes() returns trigger language plpgsql security definer set search_path='' as $$begin select coalesce(array_agg(distinct ec.class_id),'{}') into new.class_snapshot from public.exam_classes ec join public.student_enrollments se on se.class_id=ec.class_id and se.organization_id=ec.organization_id where ec.exam_id=new.exam_id and se.student_id=new.student_id and se.active;return new;end$$;
revoke all on function private.capture_attempt_classes() from public,anon,authenticated;
create trigger capture_attempt_classes before insert on public.exam_attempts for each row execute function private.capture_attempt_classes();
-- Existing rows are not assigned guessed historical classes. Admin can review them; new attempts capture IDs.
create table private.essay_grades(attempt_id uuid not null,question_id uuid not null,points numeric not null check(points>=0),comment text not null default '',source text not null check(source in ('manual','ai_accepted','ai_edited')),approved_by uuid not null references public.profiles(id),suggestion_id uuid,updated_at timestamptz not null default now(),primary key(attempt_id,question_id),foreign key(attempt_id,question_id) references private.attempt_questions(attempt_id,question_id));
create table private.grading_revisions(attempt_id uuid not null references public.exam_attempts(id),revision integer not null,engine_version text not null,actor_id uuid,reason text not null,score numeric,earned numeric not null,max_points numeric not null,pending integer not null,items jsonb not null,created_at timestamptz not null default now(),primary key(attempt_id,revision));
create table private.essay_grade_history(id uuid primary key default gen_random_uuid(),attempt_id uuid not null,question_id uuid not null,actor_id uuid not null,grade_revision integer not null,action text not null,points numeric,comment text,source text,suggestion_id uuid,created_at timestamptz not null default now(),foreign key(attempt_id,question_id) references private.attempt_questions(attempt_id,question_id));
create table private.ai_grading_suggestions(id uuid primary key default gen_random_uuid(),attempt_id uuid not null,question_id uuid not null,basis_revision integer not null,provider text not null,model text not null,prompt_version text not null,schema_version integer not null default 1,input_hash text not null,points numeric,reason text not null,status text not null check(status in ('pending','failed','accepted','edited','rejected')),requested_by uuid not null,created_at timestamptz not null default now(),foreign key(attempt_id,question_id) references private.attempt_questions(attempt_id,question_id));
create table private.grading_requests(actor_id uuid not null,request_id uuid not null,input jsonb not null,result jsonb not null,primary key(actor_id,request_id));
do $$declare t text;begin foreach t in array array['essay_grades','grading_revisions','essay_grade_history','ai_grading_suggestions','grading_requests'] loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from anon,authenticated',t);end loop;end$$;
create index essay_history_attempt on private.essay_grade_history(attempt_id,created_at desc);
create index ai_suggestions_attempt on private.ai_grading_suggestions(attempt_id,created_at desc);
create unique index grade_manual_once on public.grade_items(attempt_id,question_id) where source='manual';
create function private.is_grader() returns boolean language sql stable security definer set search_path='' as $$select private.actor_org() is not null and exists(select 1 from public.profiles where id=auth.uid() and role in ('admin','teacher') and active)$$;
create function private.can_grade(target uuid) returns boolean language sql stable security definer set search_path='' as $$select private.is_grader() and exists(select 1 from public.exam_attempts a join public.exams e on e.id=a.exam_id where a.id=target and a.organization_id=private.actor_org() and a.finalized_at is not null and a.status<>'reset' and (private.is_admin() or exists(select 1 from public.teacher_assignments t where t.teacher_id=auth.uid() and t.organization_id=a.organization_id and t.subject_id=e.subject_id and t.class_id=any(a.class_snapshot) and t.active)))$$;
create function private.recalculate_result(target uuid,reason text) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.exam_attempts;q private.attempt_questions;v jsonb;earned numeric;sum_earned numeric:=0;sum_points numeric:=0;pending int:=0;items jsonb:='[]';next_revision int;manual private.essay_grades;begin
 select * into a from public.exam_attempts where id=target for update;if not found or a.finalized_at is null or a.status='reset' then raise exception 'Attempt belum selesai';end if;
 next_revision:=a.grading_revision+1;
 for q in select * from private.attempt_questions where attempt_id=target order by position loop
 select value into v from public.attempt_answers where attempt_id=target and question_id=q.question_id;
 select * into manual from private.essay_grades where attempt_id=target and question_id=q.question_id;
 if q.grading_payload->>'type'='Esai' then earned:=manual.points;if earned is not null and earned>(q.grading_payload->>'points')::numeric then raise exception 'Nilai esai melebihi bobot';end if;
 if earned is not null then insert into public.grade_items(attempt_id,question_id,question_version,source,awarded_points,max_points,approved_by) values(target,q.question_id,q.question_version,'manual',earned,(q.grading_payload->>'points')::numeric,manual.approved_by) on conflict(attempt_id,question_id) where source='manual' do update set awarded_points=excluded.awarded_points,max_points=excluded.max_points,approved_by=excluded.approved_by;end if;
 else earned:=private.grade_one(q.grading_payload,v);
 insert into public.grade_items(attempt_id,question_id,question_version,source,awarded_points,max_points) values(target,q.question_id,q.question_version,'auto',earned,(q.grading_payload->>'points')::numeric) on conflict(attempt_id,question_id) where source='auto' do update set awarded_points=excluded.awarded_points,max_points=excluded.max_points;
 end if;
 sum_points:=sum_points+(q.grading_payload->>'points')::numeric;if earned is null then pending:=pending+1;else sum_earned:=sum_earned+earned;end if;
 items:=items||jsonb_build_array(jsonb_build_object('question_id',q.question_id,'question_version',q.question_version,'type',q.grading_payload->>'type','earned',earned,'max',(q.grading_payload->>'points')::numeric,'source',case when q.grading_payload->>'type'='Esai' then manual.source else 'auto' end));
 end loop;
 update public.exam_attempts set grading_revision=next_revision,grading_pending=pending,objective_earned=sum_earned,total_points=sum_points,score_percent=case when pending>0 then null when sum_points=0 then 0 else round(100*sum_earned/sum_points,2) end,passed=case when pending>0 or a.status='disqualified' then null else (case when sum_points=0 then 0 else round(100*sum_earned/sum_points,2) end)>=coalesce((a.policy_snapshot->>'passing_grade')::numeric,0) end where id=target returning * into a;
 insert into private.grading_revisions values(target,next_revision,'grade-v1',auth.uid(),reason,a.score_percent,sum_earned,sum_points,pending,items,clock_timestamp());
 return jsonb_build_object('attempt_id',target,'revision',next_revision,'score',a.score_percent,'pending',pending,'passed',a.passed);
end$$;
-- Finalization, manual approval and regrade now share the same ledger aggregator and grade_one primitive.
do $patch$declare definition text;begin select pg_get_functiondef('private.attempt_finalize(uuid,text)'::regprocedure) into definition;execute replace(definition,$old$insert into public.audit_logs(organization_id,actor_id,action,target_type,target_id) values(a.organization_id,auth.uid(),'ATTEMPT_FINALIZED_'||reason,'exam_attempts',target::text);$old$,$new$perform private.recalculate_result(target,'Finalisasi '||reason);insert into public.audit_logs(organization_id,actor_id,action,target_type,target_id) values(a.organization_id,auth.uid(),'ATTEMPT_FINALIZED_'||reason,'exam_attempts',target::text);$new$);end $patch$;
create function private.store_essay_grade(target uuid,qid uuid,score numeric,comment text,source text,suggestion uuid) returns void language plpgsql security definer set search_path='' as $$declare q private.attempt_questions;begin
 select * into q from private.attempt_questions where attempt_id=target and question_id=qid;if not found or q.grading_payload->>'type'<>'Esai' or score is null or score<0 or score>(q.grading_payload->>'points')::numeric or length(coalesce(comment,''))>5000 then raise exception 'Nilai esai/comment tidak valid';end if;
 insert into private.essay_grades values(target,qid,score,coalesce(comment,''),source,auth.uid(),suggestion,clock_timestamp()) on conflict(attempt_id,question_id) do update set points=excluded.points,comment=excluded.comment,source=excluded.source,approved_by=excluded.approved_by,suggestion_id=excluded.suggestion_id,updated_at=excluded.updated_at;
 insert into private.essay_grade_history(attempt_id,question_id,actor_id,grade_revision,action,points,comment,source,suggestion_id) values(target,qid,auth.uid(),(select grading_revision+1 from public.exam_attempts where id=target),'APPROVED',score,comment,source,suggestion);
end$$;
create function private.results_command(input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare op text:=input->>'action';target uuid:=nullif(input->>'attempt_id','')::uuid;exam uuid:=nullif(input->>'exam_id','')::uuid;a public.exam_attempts;row record;item jsonb;result jsonb;prior private.grading_requests;req uuid;aid uuid;sg private.ai_grading_suggestions;q private.attempt_questions;score numeric;answer jsonb;ids jsonb;page_no int;total int;begin
 if not private.is_grader() then raise exception 'AUTH: Akses Admin/Guru diperlukan';end if;
 if op='list' then
 page_no:=greatest(1,least(100000,coalesce((input->>'page')::int,1)));
 with eligible as (select ea.*,p.full_name,p.username,e.title,e.subject_id,e.show_exam_result,coalesce(s.name,'—') as subject_name,(select string_agg(c.name,', ' order by c.name) from public.classes c where c.id=any(ea.class_snapshot) and c.organization_id=ea.organization_id) as class_name from public.exam_attempts ea join public.profiles p on p.id=ea.student_id join public.exams e on e.id=ea.exam_id left join public.subjects s on s.id=e.subject_id where private.can_grade(ea.id)),filtered as(select * from eligible where (exam is null or exam_id=exam) and (nullif(input->>'class_id','') is null or (input->>'class_id')::uuid=any(class_snapshot)) and (nullif(input->>'subject_id','') is null or subject_id=(input->>'subject_id')::uuid) and (nullif(input->>'search','') is null or full_name ilike '%'||(input->>'search')||'%' or username ilike '%'||(input->>'search')||'%') and (coalesce(input->>'state','all')='all' or (input->>'state'='pending' and grading_pending>0) or (input->>'state'='final' and grading_pending=0 and status<>'disqualified') or (input->>'state'='disqualified' and status='disqualified')))
 select jsonb_build_object('total',(select count(*) from filtered),'page',page_no,'rows',coalesce(jsonb_agg(jsonb_build_object('id',f.id,'exam_id',f.exam_id,'student_id',f.student_id,'student',f.full_name,'username',f.username,'title',f.title,'subject',f.subject_name,'class_name',f.class_name,'status',f.status,'pending',f.grading_pending,'score',f.score_percent,'passed',f.passed,'revision',f.grading_revision,'started_at',f.started_at,'finalized_at',f.finalized_at,'published',f.show_exam_result)),'[]'),'can_publish',private.is_admin()) into result from (select * from filtered order by case when input->>'sort'='score_asc' then score_percent end asc nulls last,case when input->>'sort'='score_desc' then score_percent end desc nulls last,full_name,id limit 25 offset (page_no-1)*25) f;
 return result;
 end if;
 if op='detail' then
 if not private.can_grade(target) then raise exception 'AUTH: Hasil tidak dapat diakses';end if;
 select * into a from public.exam_attempts where id=target;
 select jsonb_build_object('attempt',jsonb_build_object('id',a.id,'exam_id',a.exam_id,'student_id',a.student_id,'student',(select full_name from public.profiles where id=a.student_id),'title',(select title from public.exams where id=a.exam_id),'status',a.status,'revision',a.grading_revision,'score',a.score_percent,'passed',a.passed,'pending',a.grading_pending,'class_ids',a.class_snapshot,'started_at',a.started_at,'finalized_at',a.finalized_at),'questions',coalesce((select jsonb_agg(jsonb_build_object('id',q0.question_id,'version',q0.question_version,'position',q0.position,'payload',q0.grading_payload,'answer',sa.value,'earned',case when q0.grading_payload->>'type'='Esai' then mg.points else private.grade_one(q0.grading_payload,sa.value) end,'comment',mg.comment,'source',mg.source) order by q0.position) from private.attempt_questions q0 left join public.attempt_answers sa on sa.attempt_id=q0.attempt_id and sa.question_id=q0.question_id left join private.essay_grades mg on mg.attempt_id=q0.attempt_id and mg.question_id=q0.question_id where q0.attempt_id=target),'[]'),'ledger',coalesce((select jsonb_agg(to_jsonb(g) order by revision desc) from private.grading_revisions g where g.attempt_id=target),'[]'),'history',coalesce((select jsonb_agg(to_jsonb(h) order by created_at desc) from private.essay_grade_history h where h.attempt_id=target),'[]'),'suggestions',coalesce((select jsonb_agg(to_jsonb(sg0) order by created_at desc) from private.ai_grading_suggestions sg0 where sg0.attempt_id=target),'[]')) into result;return result;
 end if;
 req:=(input->>'request_id')::uuid;if req is null then raise exception 'Request ID wajib';end if;
 for aid in select distinct (entry->>'attempt_id')::uuid from jsonb_array_elements(coalesce(input->'grades',input->'items','[]')) entry union select value::uuid from jsonb_array_elements_text(coalesce(input->'ids','[]')) loop if not private.can_grade(aid) then raise exception 'AUTH: Cakupan hasil telah berubah';end if;end loop;
 if op in ('accept_ai','edit_ai','reject_ai') and not exists(select 1 from private.ai_grading_suggestions s where s.id=(input->>'suggestion_id')::uuid and private.can_grade(s.attempt_id)) then raise exception 'AUTH: Saran di luar cakupan';end if;
 if op='publish' and not private.is_admin() then raise exception 'AUTH: Hanya Admin menerbitkan nilai';end if;
 select * into prior from private.grading_requests r where r.actor_id=auth.uid() and r.request_id=req;if found then if prior.input<>input then raise exception 'IDEMPOTENCY_CONFLICT';end if;return prior.result;end if;
 if op='publish' then
 if not private.is_admin() or not exists(select 1 from public.exams where id=exam and organization_id=private.actor_org()) then raise exception 'AUTH: Hanya Admin menerbitkan nilai';end if;
 update public.exams set show_exam_result=(input->>'published')::boolean where id=exam;result:=jsonb_build_object('saved',true);
 elsif op='grade_batch' then
 if jsonb_typeof(input->'grades') is distinct from 'array' or jsonb_array_length(input->'grades') not between 1 and 500 or (select count(distinct (v->>'attempt_id')||':'||(v->>'question_id')) from jsonb_array_elements(input->'grades') v)<>jsonb_array_length(input->'grades') then raise exception 'Batch 1–500 nilai unik';end if;
 for aid in select distinct (v->>'attempt_id')::uuid from jsonb_array_elements(input->'grades') v order by 1 loop
 if not private.can_grade(aid) then raise exception 'AUTH: Koreksi di luar cakupan';end if;select * into a from public.exam_attempts where id=aid for update;
 if a.status='disqualified' then raise exception 'Attempt diskualifikasi tidak dapat dinilai';end if;
 if exists(select 1 from jsonb_array_elements(input->'grades') v where (v->>'attempt_id')::uuid=aid and (v->>'expected_revision')::int is distinct from a.grading_revision) then raise exception 'CONFLICT: Hasil telah berubah; muat ulang';end if;
 end loop;
 for item in select * from jsonb_array_elements(input->'grades') loop
 if jsonb_typeof(item->'points') is distinct from 'number' then raise exception 'Nilai numerik wajib';end if;
 perform private.store_essay_grade((item->>'attempt_id')::uuid,(item->>'question_id')::uuid,(item->>'points')::numeric,item->>'comment','manual',null);end loop;
 result:='[]';for aid in select distinct (v->>'attempt_id')::uuid from jsonb_array_elements(input->'grades') v order by 1 loop result:=result||jsonb_build_array(private.recalculate_result(aid,'Koreksi manual batch'));end loop;
 elsif op='recalculate' then
 if length(trim(coalesce(input->>'reason','')))<5 or jsonb_array_length(input->'ids') not between 1 and 500 then raise exception 'Alasan dan 1–500 attempt wajib';end if;
 result:='[]';for aid in select distinct v::uuid from jsonb_array_elements_text(input->'ids') v order by 1 loop
 if not private.can_grade(aid) then raise exception 'AUTH: Rekalkulasi di luar cakupan';end if;select * into a from public.exam_attempts where id=aid for update;
 if (input->'expected'->>aid::text)::int is distinct from a.grading_revision then raise exception 'CONFLICT: Hasil berubah';end if;
 result:=result||jsonb_build_array(private.recalculate_result(aid,input->>'reason'));end loop;
 elsif op='request_ai' then
 if jsonb_array_length(input->'items') not between 1 and 50 then raise exception 'AI maksimal 50 item';end if;
 if not public.consume_login_budget('ai-grading:'||auth.uid()::text) then return jsonb_build_object('error','Terlalu banyak permintaan AI. Coba lagi dalam 15 menit.','status',429);end if;
 for aid in select distinct (v->>'attempt_id')::uuid from jsonb_array_elements(input->'items') v order by 1 loop if not private.can_grade(aid) then raise exception 'AUTH: AI di luar cakupan';end if;perform 1 from public.exam_attempts where id=aid for update;end loop;
 result:='[]';for item in select * from jsonb_array_elements(input->'items') loop
 aid:=(item->>'attempt_id')::uuid;if not private.can_grade(aid) then raise exception 'AUTH: AI di luar cakupan';end if;select * into a from public.exam_attempts where id=aid for update;
 select * into q from private.attempt_questions where attempt_id=aid and question_id=(item->>'question_id')::uuid;if not found or q.grading_payload->>'type'<>'Esai' then raise exception 'AI hanya untuk esai snapshot';end if;
 select value into answer from public.attempt_answers where attempt_id=aid and question_id=q.question_id;
 insert into private.ai_grading_suggestions(attempt_id,question_id,basis_revision,provider,model,prompt_version,input_hash,points,reason,status,requested_by) values(aid,q.question_id,a.grading_revision,'unconfigured','none','essay-rubric-v1',encode(extensions.digest(jsonb_build_object('question',q.grading_payload->>'stem','rubric',q.grading_payload->>'rubric','answer',answer)::text,'sha256'),'hex'),null,'Penyedia AI dan persetujuan data belum dikonfigurasi','failed',auth.uid()) returning id into target;result:=result||jsonb_build_array(jsonb_build_object('id',target,'status','failed','points',null));end loop;
 result:=jsonb_build_object('configured',false,'status',503,'message','AI belum dikonfigurasi; koreksi manual tetap tersedia. Tidak ada nilai nol yang disimpan sebagai saran.','items',result);
 elsif op in ('accept_ai','edit_ai','reject_ai') then
 select * into sg from private.ai_grading_suggestions where id=(input->>'suggestion_id')::uuid for update;if not found or not private.can_grade(sg.attempt_id) then raise exception 'AUTH: Saran tidak tersedia';end if;
 select * into a from public.exam_attempts where id=sg.attempt_id for update;
 if sg.status<>'pending' or sg.points is null or sg.basis_revision<>a.grading_revision or (input->>'expected_revision')::int is distinct from a.grading_revision then raise exception 'CONFLICT: Saran gagal, sudah diputuskan, atau kedaluwarsa';end if;
 if op='reject_ai' then
 update private.ai_grading_suggestions set status='rejected' where id=sg.id;insert into private.essay_grade_history(attempt_id,question_id,actor_id,grade_revision,action,comment,suggestion_id) values(sg.attempt_id,sg.question_id,auth.uid(),a.grading_revision,'REJECTED',input->>'comment',sg.id);result:=jsonb_build_object('rejected',true);
 else
 score:=case when op='edit_ai' then (input->>'points')::numeric else sg.points end;
 perform private.store_essay_grade(sg.attempt_id,sg.question_id,score,input->>'comment',case when op='edit_ai' then 'ai_edited' else 'ai_accepted' end,sg.id);
 update private.ai_grading_suggestions set status=case when op='edit_ai' then 'edited' else 'accepted' end where id=sg.id;result:=private.recalculate_result(sg.attempt_id,'Persetujuan saran AI');end if;
 else raise exception 'Aksi hasil tidak dikenal';end if;
 insert into private.grading_requests values(auth.uid(),req,input,result);
 insert into public.audit_logs(organization_id,actor_id,action,target_type,target_id) values(private.actor_org(),auth.uid(),'RESULTS_'||op,'grading',coalesce(exam,target)::text);return result;
end$$;
create function public.results_command(input jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.results_command(input)$$;
revoke all on function private.is_grader(),private.can_grade(uuid),private.recalculate_result(uuid,text),private.store_essay_grade(uuid,uuid,numeric,text,text,uuid),private.results_command(jsonb),public.results_command(jsonb) from public,anon,authenticated;
grant execute on function private.can_grade(uuid),private.results_command(jsonb),public.results_command(jsonb) to authenticated;
-- Staff may read only answer/source assets used by an attempt they can grade.
create function private.can_grade_media(path text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.answer_media am where am.object_path=path and private.can_grade(am.attempt_id)) or exists(select 1 from public.media_assets m join private.attempt_questions q on q.grading_payload->'attachments' ? m.id::text where m.object_path=path and private.can_grade(q.attempt_id))$$;
revoke all on function private.can_grade_media(text) from public,anon;grant execute on function private.can_grade_media(text) to authenticated;
create policy grader_answer_media on public.answer_media for select to authenticated using(private.can_grade(attempt_id));
create policy grader_source_media on public.media_assets for select to authenticated using(private.can_grade_media(object_path));
create policy grader_media_storage on storage.objects for select to authenticated using(bucket_id in ('exam-media','attempt-canvas') and private.can_grade_media(name));

create function private.result_detail(target uuid,revision_no integer default null) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.exam_attempts;g private.grading_revisions;rev int;result jsonb;begin
 if not private.can_grade(target) then raise exception 'AUTH: Hasil tidak tersedia';end if;select * into a from public.exam_attempts where id=target;rev:=coalesce(revision_no,a.grading_revision);
 select * into g from private.grading_revisions where attempt_id=target and revision=rev;if revision_no is not null and not found then raise exception 'Versi ledger ekspor tidak tersedia';end if;
 select jsonb_build_object('attempt',jsonb_build_object('id',a.id,'exam_id',a.exam_id,'student_id',a.student_id,'student',(select full_name from public.profiles where id=a.student_id),'title',(select title from public.exams where id=a.exam_id),'status',a.status,'revision',rev,'score',case when rev=0 then a.score_percent else g.score end,'passed',case when coalesce(g.pending,a.grading_pending)>0 or a.status='disqualified' then null else coalesce(g.score,a.score_percent)>=coalesce((a.policy_snapshot->>'passing_grade')::numeric,0) end,'pending',coalesce(g.pending,a.grading_pending),'class_ids',a.class_snapshot,'class_name',(select string_agg(name,', ' order by name) from public.classes where id=any(a.class_snapshot)),'started_at',a.started_at,'finalized_at',a.finalized_at),'questions',coalesce((select jsonb_agg(jsonb_build_object('id',q.question_id,'version',q.question_version,'position',q.position,'payload',q.grading_payload,'answer',sa.value,'earned',case when rev=0 then private.grade_one(q.grading_payload,sa.value) else (gi.value->>'earned')::numeric end,'comment',h.comment,'source',gi.value->>'source') order by q.position) from private.attempt_questions q left join public.attempt_answers sa on sa.attempt_id=q.attempt_id and sa.question_id=q.question_id left join lateral(select value from jsonb_array_elements(coalesce(g.items,'[]')) where value->>'question_id'=q.question_id::text)gi on true left join lateral(select comment from private.essay_grade_history h0 where h0.attempt_id=target and h0.question_id=q.question_id and h0.action='APPROVED' and h0.grade_revision<=rev order by h0.grade_revision desc,h0.created_at desc limit 1)h on true where q.attempt_id=target),'[]'),'ledger',coalesce((select jsonb_agg(to_jsonb(r) order by r.revision desc) from private.grading_revisions r where r.attempt_id=target and r.revision<=rev),'[]'),'history',coalesce((select jsonb_agg(to_jsonb(h0) order by h0.grade_revision desc,h0.created_at desc) from private.essay_grade_history h0 where h0.attempt_id=target and h0.grade_revision<=rev),'[]'),'suggestions',case when revision_no is null then coalesce((select jsonb_agg(to_jsonb(sg) order by created_at desc) from private.ai_grading_suggestions sg where attempt_id=target),'[]') else '[]'::jsonb end) into result;
 return result;end$$;
revoke all on function private.result_detail(uuid,integer) from public,anon,authenticated;
-- Use one DTO builder for the UI, analytic cohorts and version-pinned reports.
do $patch$declare definition text;start_pos int;end_pos int;begin select pg_get_functiondef('private.results_command(jsonb)'::regprocedure) into definition;start_pos:=position(' if op=''detail'' then' in definition);end_pos:=position(' req:=(input->>''request_id'')::uuid;' in definition);if start_pos=0 or end_pos<=start_pos then raise exception 'Detail handler marker missing';end if;definition:=substring(definition,1,start_pos-1)||E' if op=''detail'' then return private.result_detail(target,null);end if;\n'||substring(definition,end_pos);execute definition;end $patch$;
create table private.report_settings(organization_id uuid primary key references public.organizations(id),school text not null,address text not null default '',official text not null default '',official_title text not null default '',logo_media_id uuid references public.media_assets(id));
create table private.export_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),requested_by uuid not null references public.profiles(id),request_id uuid not null,input jsonb not null,attempt_ids uuid[] not null,versions jsonb not null,settings_snapshot jsonb not null,labels jsonb not null,kind text not null check(kind in ('recap','class','student','paper','answers','blank','analytics')),format text not null check(format in ('pdf','xlsx')),status text not null default 'queued' check(status in ('queued','running','ready','failed')),progress int not null default 0 check(progress between 0 and 100),failures int not null default 0,lease uuid,lease_until timestamptz,result_path text,byte_size bigint,error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(requested_by,request_id));
alter table private.report_settings enable row level security;alter table private.export_jobs enable row level security;
revoke all on private.report_settings,private.export_jobs from public,anon,authenticated;
create index export_jobs_owner_time on private.export_jobs(requested_by,created_at desc);
create function private.job_access(target uuid) returns boolean language sql stable security definer set search_path='' as $$select private.is_grader() and exists(select 1 from private.export_jobs j where j.id=target and j.requested_by=auth.uid() and j.organization_id=private.actor_org() and not exists(select 1 from unnest(j.attempt_ids) as member(attempt_id) where not private.can_grade(member.attempt_id)))$$;
create function private.report_logo_allowed(target uuid) returns boolean language sql stable security definer set search_path='' as $$select private.is_grader() and exists(select 1 from private.report_settings s where s.organization_id=private.actor_org() and s.logo_media_id=target)$$;
create policy report_logo_media on public.media_assets for select to authenticated using(private.report_logo_allowed(id));
create policy report_logo_storage on storage.objects for select to authenticated using(bucket_id='exam-media' and exists(select 1 from public.media_assets m where m.object_path=name and private.report_logo_allowed(m.id)));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('exam-reports','exam-reports',false,52428800,array['application/pdf','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);
create function private.report_object_access(path text,writing boolean default false) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from private.export_jobs j where private.job_access(j.id) and split_part(path,'/',1)=auth.uid()::text and split_part(path,'/',2)=j.id::text and (not writing or (j.status='running' and j.lease_until>clock_timestamp() and split_part(path,'/',3)=j.lease::text)))$$;
create policy reports_read on storage.objects for select to authenticated using(bucket_id='exam-reports' and private.report_object_access(name,false));
create policy reports_insert on storage.objects for insert to authenticated with check(bucket_id='exam-reports' and private.report_object_access(name,true));
create function private.report_command(input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare op text:=input->>'action';target uuid:=nullif(input->>'job_id','')::uuid;j private.export_jobs;settings jsonb;ids uuid[];aid uuid;versions jsonb:='{}';labels jsonb:='{}';detail jsonb;result jsonb;req uuid;bytes bigint;begin
 if not private.is_grader() then raise exception 'AUTH: Akses laporan diperlukan';end if;
 if op='settings_get' then select to_jsonb(s)-'organization_id' into result from private.report_settings s where organization_id=private.actor_org();return coalesce(result,jsonb_build_object('school',(select name from public.organizations where id=private.actor_org()),'address','','official','','official_title','','logo_media_id',null))||jsonb_build_object('can_manage',private.is_admin());end if;
 if op='settings' then
 if not private.is_admin() then raise exception 'AUTH: Hanya Admin mengatur kop';end if;
 if length(trim(input->>'school')) not between 1 and 200 or length(coalesce(input->>'address',''))>1000 or length(coalesce(input->>'official',''))>150 or length(coalesce(input->>'official_title',''))>150 then raise exception 'Kop tidak valid';end if;
 if nullif(input->>'logo_media_id','') is not null and not exists(select 1 from public.media_assets where id=(input->>'logo_media_id')::uuid and organization_id=private.actor_org() and mime_type in ('image/png','image/jpeg','image/webp')) then raise exception 'Logo tidak sah';end if;
 insert into private.report_settings values(private.actor_org(),input->>'school',coalesce(input->>'address',''),coalesce(input->>'official',''),coalesce(input->>'official_title',''),nullif(input->>'logo_media_id','')::uuid) on conflict(organization_id) do update set school=excluded.school,address=excluded.address,official=excluded.official,official_title=excluded.official_title,logo_media_id=excluded.logo_media_id;return jsonb_build_object('saved',true);end if;
 if op='analysis' then
 if jsonb_array_length(input->'ids') not between 1 and 500 then raise exception 'Pilih 1–500 attempt';end if;result:='[]';for aid in select distinct value::uuid from jsonb_array_elements_text(input->'ids') loop result:=result||jsonb_build_array(private.result_detail(aid,null));end loop;return result;end if;
 if op='list' then select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'kind',s.kind,'format',s.format,'status',s.status,'progress',s.progress,'failures',s.failures,'error',s.error,'created_at',s.created_at) order by s.created_at desc),'[]') into result from (select * from private.export_jobs j0 where requested_by=auth.uid() and private.job_access(j0.id) order by created_at desc limit 50)s;return result;end if;
 if op='create' then
 req:=(input->>'request_id')::uuid;if req is null or jsonb_array_length(input->'ids') not between 1 and 500 or input->>'kind' not in ('recap','class','student','paper','answers','blank','analytics') or input->>'format' not in ('pdf','xlsx') then raise exception 'Format job tidak valid';end if;
 select array_agg(distinct value::uuid order by value::uuid) into ids from jsonb_array_elements_text(input->'ids');
 foreach aid in array ids loop
 if not private.can_grade(aid) then raise exception 'AUTH: Laporan di luar cakupan';end if;
 select grading_revision into bytes from public.exam_attempts where id=aid;if bytes<1 then raise exception 'Rekalkulasi hasil berizin diperlukan sebelum ekspor ledger lama';end if;versions:=versions||jsonb_build_object(aid::text,bytes);
 detail:=private.result_detail(aid,bytes::int);labels:=labels||jsonb_build_object(aid::text,detail->'attempt');end loop;
 select * into j from private.export_jobs where requested_by=auth.uid() and request_id=req;if found then if j.input<>input then raise exception 'IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('id',j.id,'status',j.status);end if;
 if not public.consume_login_budget('report-create:'||auth.uid()::text) then return jsonb_build_object('error','Batas permintaan laporan tercapai. Coba lagi dalam 15 menit.','status',429);end if;
 settings:=private.report_command('{"action":"settings_get"}'::jsonb)-'can_manage';
 insert into private.export_jobs(organization_id,requested_by,request_id,input,attempt_ids,versions,settings_snapshot,labels,kind,format) values(private.actor_org(),auth.uid(),req,input,ids,versions,settings,labels,input->>'kind',input->>'format') returning id into target;return jsonb_build_object('id',target,'status','queued');end if;
 if not private.job_access(target) then raise exception 'AUTH: Job tidak tersedia atau izin berubah';end if;
 select * into j from private.export_jobs where id=target for update;
 if op='status' then return jsonb_build_object('id',j.id,'status',j.status,'progress',j.progress,'failures',j.failures,'error',j.error,'kind',j.kind,'format',j.format);end if;
 if op='claim' then
 if j.status='ready' then return jsonb_build_object('ready',true);end if;
 if j.status='running' and j.lease_until>clock_timestamp() then return jsonb_build_object('busy',true);end if;
 if j.failures>=5 then raise exception 'Batas retry job tercapai; buat job baru setelah memperbaiki penyebab';end if;
 update private.export_jobs set status='running',progress=1,lease=gen_random_uuid(),lease_until=clock_timestamp()+interval '4 minutes',error=null,updated_at=clock_timestamp() where id=target returning * into j;
 return jsonb_build_object('id',j.id,'lease',j.lease,'ids',j.attempt_ids,'settings',j.settings_snapshot,'kind',j.kind,'format',j.format,'requested_by',j.requested_by,'created_at',j.created_at);end if;
 if op='download' then if j.status<>'ready' or j.result_path is null then raise exception 'Laporan belum siap';end if;return jsonb_build_object('path',j.result_path,'kind',j.kind,'format',j.format,'bytes',j.byte_size);end if;
 if j.status<>'running' or j.lease is distinct from (input->>'lease')::uuid or j.lease_until<clock_timestamp() then raise exception 'CONFLICT: Lease job berubah/kedaluwarsa';end if;
 if op='data' then result:='[]';for aid in select x.id from unnest(j.attempt_ids) with ordinality x(id,n) where n>coalesce((input->>'offset')::int,0) and n<=coalesce((input->>'offset')::int,0)+10 order by n loop detail:=private.result_detail(aid,(j.versions->>aid::text)::int);detail:=jsonb_set(detail,'{attempt}',j.labels->aid::text);result:=result||jsonb_build_array(detail);end loop;return result;end if;
 if op='progress' then update private.export_jobs set progress=greatest(progress,least(95,greatest(1,(input->>'progress')::int))),lease_until=clock_timestamp()+interval '4 minutes',updated_at=clock_timestamp() where id=target;return jsonb_build_object('saved',true);end if;
 if op='finish' then
 if (input->>'path') not like j.requested_by::text||'/'||j.id::text||'/'||j.lease::text||'/%.'||j.format then raise exception 'Path laporan tidak valid';end if;
 select (metadata->>'size')::bigint into bytes from storage.objects where bucket_id='exam-reports' and name=input->>'path';if bytes is null or bytes not between 1 and 52428800 then raise exception 'Artefak belum tersimpan atau melebihi 50 MiB';end if;
 update private.export_jobs set status='ready',progress=100,result_path=input->>'path',byte_size=bytes,updated_at=clock_timestamp() where id=target;return jsonb_build_object('ready',true);end if;
 if op='fail' then update private.export_jobs set status='failed',failures=failures+1,error=left(coalesce(input->>'message','Ekspor gagal'),500),updated_at=clock_timestamp() where id=target;return jsonb_build_object('failed',true);end if;
 raise exception 'Aksi job tidak dikenal';end$$;
create function public.report_command(input jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.report_command(input)$$;
revoke all on function private.job_access(uuid),private.report_logo_allowed(uuid),private.report_object_access(text,boolean),private.report_command(jsonb),public.report_command(jsonb) from public,anon,authenticated;
grant execute on function private.job_access(uuid),private.report_logo_allowed(uuid),private.report_object_access(text,boolean),private.report_command(jsonb),public.report_command(jsonb) to authenticated;
